(()=>{if(window.parent===window)return;const origin=location.origin,file=location.pathname.replace(/^\/__editor\/preview\/(portfolio|games|ui)\//,'')||'index.html';let selected='',picking=false;const post=message=>parent.postMessage({channel:'portfolio-design',file,...message},origin);const all=()=>Array.from(document.querySelectorAll('[data-edit-key]'));const label=node=>{let value=node.classList.contains('source-rich')?node.textContent.trim().replace(/\s+/g,' '):(node.matches('img')?node.alt:node.querySelector('img')?.alt)||node.className.split(' ')[0].replaceAll('-',' ');return value.slice(0,72)||'Component'};const list=()=>post({type:'components',components:all().map(node=>{const s=getComputedStyle(node);return {key:node.dataset.editKey,label:label(node),text:node.classList.contains('source-rich'),defaults:{font:s.fontFamily,size:parseFloat(s.fontSize),bold:parseInt(s.fontWeight)>=600,before:parseFloat(s.marginTop)||0,after:parseFloat(s.marginBottom)||0}}})});const mark=()=>{for(const n of all())n.toggleAttribute('data-design-selected',n.dataset.editKey===selected);document.documentElement.toggleAttribute('data-design-picking',picking)};const hint=document.createElement('style');hint.textContent='[data-design-selected]{outline:2px solid #287bb5!important;outline-offset:3px}html[data-design-picking] [data-edit-key]:hover{outline:2px dashed #287bb5!important;cursor:pointer!important}';document.head.append(hint);document.addEventListener('click',e=>{if(!picking)return;const node=e.target.closest('[data-edit-key]');if(!node)return;e.preventDefault();e.stopImmediatePropagation();selected=node.dataset.editKey;mark();post({type:'select',key:selected})},true);window.addEventListener('message',e=>{if(e.source!==parent||e.origin!==origin||e.data?.channel!=='portfolio-design')return;const m=e.data;if(m.type==='request')list();if(m.type==='settings'){let style=document.querySelector('#component-design');if(!style){style=document.createElement('style');style.id='component-design';document.head.append(style)}style.textContent=designCSS(m.settings||{});selected=m.selected||'';picking=!!m.picking;mark();if(m.scroll&&selected)all().find(n=>n.dataset.editKey===selected)?.scrollIntoView({block:'center',behavior:'smooth'})}});list()})();
